From 717d6cf52ce6048c27dc67ee6565ab6f3681ecd9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:09:17 +0100
Subject: [PATCH] activitymanager: show Picture of the Day and slideshow
 wallpapers

Activity tiles only read image and color wallpapers, so an activity with
Picture of the Day or a slideshow kept a stale or default tile. Read the
Image entry, where both now save the picture they show, like Image does.

BUG: 449823
---
 imports/activitymanager/sortedactivitiesmodel.cpp | 8 +++++---
 1 file changed, 5 insertions(+), 3 deletions(-)

diff --git a/imports/activitymanager/sortedactivitiesmodel.cpp b/imports/activitymanager/sortedactivitiesmodel.cpp
index f200d0655d..0ca1618dda 100644
--- a/imports/activitymanager/sortedactivitiesmodel.cpp
+++ b/imports/activitymanager/sortedactivitiesmodel.cpp
@@ -135,14 +135,16 @@ public:
         auto wallpaperPlugin = config.readEntry("wallpaperplugin");
         auto wallpaperConfig = config.group(QStringLiteral("Wallpaper")).group(wallpaperPlugin).group(QStringLiteral("General"));

-        if (wallpaperPlugin == u"org.kde.image") {
+        if (wallpaperPlugin == u"org.kde.image" || wallpaperPlugin == u"org.kde.slideshow" || wallpaperPlugin == u"org.kde.potd") {
             // we can have three cases:
             // - Image is a URL to a specific image -> use that
             // - Image is a URL to a wallpaper package folder -> pick one image from that folder
             // - Image is empty -> use default wallpaper
+            // Slideshow and Picture of the Day store the image they show in Image as well.

-            const QUrl defaultWallpaper =
-                QUrl::fromLocalFile(QStandardPaths::locate(QStandardPaths::GenericDataLocation, u"wallpapers/Next"_s, QStandardPaths::LocateDirectory));
+            const QUrl defaultWallpaper = wallpaperPlugin == u"org.kde.image"
+                ? QUrl::fromLocalFile(QStandardPaths::locate(QStandardPaths::GenericDataLocation, u"wallpapers/Next"_s, QStandardPaths::LocateDirectory))
+                : QUrl();

             const QUrl wallpaper = wallpaperConfig.readEntry("Image", defaultWallpaper);

-- 
2.53.0

From b0267d670567703d11e12c7f3e7ee499d0495968 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 00:28:31 +0100
Subject: [PATCH] wallpapers/image: save the current slide when it changes

The slideshow only wrote its current slide to disk on quit, so the
activity switcher showed a slide from the previous session at best. Also
write it after each change, at most once every five seconds.

BUG: 449823
---
 wallpapers/image/imagepackage/contents/ui/main.qml | 8 ++++++++
 1 file changed, 8 insertions(+)

diff --git a/wallpapers/image/imagepackage/contents/ui/main.qml b/wallpapers/image/imagepackage/contents/ui/main.qml
index 14aac831f8..e4fa32dae9 100644
--- a/wallpapers/image/imagepackage/contents/ui/main.qml
+++ b/wallpapers/image/imagepackage/contents/ui/main.qml
@@ -99,10 +99,18 @@ WallpaperItem {
             // Invoked from C++
             function writeImageConfig(newImage: string) {
                 configMap.Image = newImage;
+                saveSlideTimer.start();
             }
         }
     }

+    // Save the current slide so that others, like the activity switcher, can show it
+    Timer {
+        id: saveSlideTimer
+        interval: 5000
+        onTriggered: root.configuration.writeConfig()
+    }
+
     Component.onDestruction: {
         if (root.pluginName === "org.kde.slideshow") {
             root.configuration.writeConfig(); // Save the last position
-- 
